<?php
if(PHP_SAPI!=='cli')exit(1);$root=dirname(__DIR__);$copy=$root.'/protected/runtime/tree-check-'.bin2hex(random_bytes(5)).'.sqlite';copy($root.'/protected/runtime/store.sqlite',$copy);putenv('SHOP_DSN=sqlite:'.$copy);require __DIR__.'/bootstrap.php';$checks=0;
function treeCheck($ok,$message){global $checks;if(!$ok)throw new Exception('FAILED '.$message);$checks++;echo 'PASS '.$message."\n";}
function treeReject($fn,$status,$message){$before=CategoryTreeService::revision();try{$fn();}catch(CHttpException $e){treeCheck($e->statusCode===$status&&CategoryTreeService::revision()===$before,$message);return;}treeCheck(false,$message);}
function addTreeCategory($slug,$parent=null){$c=new Category;$c->name=$slug;$c->slug=$slug;$c->description='';$c->parent_id=$parent;if(!Hierarchy::save($c))throw new Exception('seed failure');return $c->id;}
try{$a=addTreeCategory('tree-root-a');$b=addTreeCategory('tree-root-b');$child=addTreeCategory('tree-child',$a);$grand=addTreeCategory('tree-grandchild',$child);$other=addTreeCategory('tree-other',$b);
$old=CategoryTreeService::revision();CategoryTreeService::move($child,$b,'inside',$old);treeCheck((int)Category::model()->findByPk($child)->parent_id===(int)$b,'move subtree to new parent');treeCheck((int)Category::model()->findByPk($grand)->parent_id===(int)$child,'descendants travel with subtree');treeReject(function()use($a,$b,$old){CategoryTreeService::move($a,$b,'inside',$old);},409,'stale drag revision rejected without writes');treeReject(function()use($b,$grand){CategoryTreeService::move($b,$grand,'inside',CategoryTreeService::revision());},422,'descendant cycle rejected');treeReject(function()use($child){CategoryTreeService::move($child,$child,'after',CategoryTreeService::revision());},422,'self target rejected');
CategoryTreeService::move($child,$other,'before',CategoryTreeService::revision());$siblings=Category::model()->findAll(array('condition'=>'parent_id=:p','params'=>array(':p'=>$b),'order'=>'sort_order,id'));treeCheck(array_map(function($c){return (int)$c->id;},$siblings)===array((int)$child,(int)$other),'before drop changes sibling order');CategoryTreeService::move($child,$other,'after',CategoryTreeService::revision());treeCheck((int)Category::model()->findByPk($child)->sort_order===1,'after drop changes sibling order');CategoryTreeService::move($child,0,'root',CategoryTreeService::revision());treeCheck(!Category::model()->findByPk($child)->parent_id,'drop on root removes parent');treeCheck((int)Category::model()->findByPk($other)->sort_order===0,'source siblings compact after removal');
treeReject(function()use($a){CategoryTreeService::move($a,999999,'inside',CategoryTreeService::revision());},422,'unknown drop target rejected');treeReject(function()use($a,$b){CategoryTreeService::move($a,$b,'invalid',CategoryTreeService::revision());},422,'unknown drop operation rejected');$model=Category::model()->findByPk($a);$name=$model->name;$model->name='unsaved';treeReject(function()use($model,$old){Hierarchy::save($model,$old);},409,'stale edit revision rejected');treeCheck(Category::model()->findByPk($a)->name===$name,'stale edit keeps persisted metadata');echo "All $checks tree checks passed on isolated database.\n";
}finally{Yii::app()->db->active=false;@unlink($copy);}
